rule_select_stmt(select_stmt(L162,none,none)) --> cl_7(L162).


% ============================================================ expression ladder
expr(E) --> lvl_or(E).

% level pow — exponent; one shot (2 ** 3 ** 2 is not folded — not needed here)
lvl_pow(pow(A,B)) --> prim(A), [tok(symbol,'**')], prim(B).
lvl_pow(E) --> prim(E).

% level unary — unary minus
lvl_unary(neg(E)) --> [tok(symbol,'-')], lvl_unary(E).
lvl_unary(E) --> lvl_pow(E).

% level mul
lvl_mul(E) --> lvl_unary(L0), lvl_mul_rest(L0, E).
lvl_mul_rest(L0, E) --> [tok(symbol,'*')], lvl_unary(R), lvl_mul_rest(mul(L0,R), E).
lvl_mul_rest(L0, E) --> [tok(symbol,'/')], lvl_unary(R), lvl_mul_rest(div(L0,R), E).
lvl_mul_rest(E, E) --> [].

% level add
lvl_add(E) --> lvl_mul(L0), lvl_add_rest(L0, E).
lvl_add_rest(L0, E) --> [tok(symbol,'+')], lvl_mul(R), lvl_add_rest(add(L0,R), E).
lvl_add_rest(L0, E) --> [tok(symbol,'-')], lvl_mul(R), lvl_add_rest(sub(L0,R), E).
lvl_add_rest(E, E) --> [].

% level cat — string concatenation
lvl_cat(E) --> lvl_add(L0), lvl_cat_rest(L0, E).
lvl_cat_rest(L0, E) --> [tok(symbol,'||')], lvl_add(R), lvl_cat_rest(cat(L0,R), E).
lvl_cat_rest(E, E) --> [].

% level cmp — comparisons do not chain; `<>` is read as NE (its PROC SQL meaning)
lvl_cmp(eq(A,B)) --> lvl_cat(A), [tok(symbol,'=')], lvl_cat(B).
lvl_cmp(eq(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'eq') }, lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'^=')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'~=')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(symbol,'<>')], lvl_cat(B).
lvl_cmp(ne(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'ne') }, lvl_cat(B).
lvl_cmp(lt(A,B)) --> lvl_cat(A), [tok(symbol,'<')], lvl_cat(B).
lvl_cmp(lt(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'lt') }, lvl_cat(B).
lvl_cmp(le(A,B)) --> lvl_cat(A), [tok(symbol,'<=')], lvl_cat(B).
lvl_cmp(le(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'le') }, lvl_cat(B).
lvl_cmp(gt(A,B)) --> lvl_cat(A), [tok(symbol,'>')], lvl_cat(B).
lvl_cmp(gt(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'gt') }, lvl_cat(B).
lvl_cmp(ge(A,B)) --> lvl_cat(A), [tok(symbol,'>=')], lvl_cat(B).
lvl_cmp(ge(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'ge') }, lvl_cat(B).
lvl_cmp(in(A,B)) --> lvl_cat(A), [tok(keyword,K)], { downcase_atom(K,'in') }, [tok(symbol,'(')], args(B), [tok(symbol,')')].
lvl_cmp(E) --> lvl_cat(E).

% level not
lvl_not(not(E)) --> [tok(keyword,K)], { downcase_atom(K,'not') }, lvl_not(E).
lvl_not(E) --> lvl_cmp(E).

% level and
lvl_and(E) --> lvl_not(L0), lvl_and_rest(L0, E).
lvl_and_rest(L0, E) --> [tok(keyword,K)], { downcase_atom(K,'and') }, lvl_not(R), lvl_and_rest(and(L0,R), E).
lvl_and_rest(E, E) --> [].

% level or
lvl_or(E) --> lvl_and(L0), lvl_or_rest(L0, E).
lvl_or_rest(L0, E) --> [tok(keyword,K)], { downcase_atom(K,'or') }, lvl_and(R), lvl_or_rest(or(L0,R), E).
lvl_or_rest(E, E) --> [].

% forms — tried before the bare leaves so a call/qcol/positional
% prefix is matched whole; Prolog backtracking makes the try-then-
% fall-through safe (no lookahead needed).
prim(case_expr(L15,some(Else17))) --> [tok(keyword,K1)], { downcase_atom(K1,'case') }, cl_1(L15), [tok(keyword,K16)], { downcase_atom(K16,'else') }, expr(Else17), [tok(keyword,K18)], { downcase_atom(K18,'end') }.
prim(case_expr(L15,none)) --> [tok(keyword,K1)], { downcase_atom(K1,'case') }, cl_1(L15), [tok(keyword,K18)], { downcase_atom(K18,'end') }.
prim(missing) --> [tok(symbol,'.')].
prim(star) --> [tok(symbol,'*')].
prim(paren(E)) --> [tok(symbol,'(')], expr(E), [tok(symbol,')')].
prim(call(N,Args)) --> ( [tok(word,N)] ; [tok(keyword,N)] ), [tok(symbol,'(')], args(Args), [tok(symbol,')')].
prim(col(N,F)) --> [tok(word,N)], [tok(symbol,'.')], [tok(word,F)].
prim(subquery_expr(V)) --> [tok(symbol,'(')], rule_select_core(V), [tok(symbol,')')].

% leaves — token kind == leaf name, by convention (see pydsl_lib.leaf)
prim(lit(N)) --> [tok(number,V)], { atom_number(V,N) }.
prim(lit(S)) --> [tok(string,V)], { unquote_plain(V, S) }.
prim(col(N)) --> [tok(word,N)].

args([A|As]) --> expr(A), args_rest(As).
args([]) --> [].
args_rest([A|As]) --> [tok(symbol,',')], expr(A), args_rest(As).
args_rest([]) --> [].

% ============================================================ print direction
print_stmt_libname(libname(Lib191,Path192), T194) :- print_expr(Path192, 0, T193), flatten([['libname'], [Lib191], T193, [';']], T194).
print_stmt(T, Texts) :- print_stmt_libname(T, Texts), !.

print_stmt_data(data(Out197), T199) :- print_rule_dsname(Out197, T198), flatten([['data'], T198, [';']], T199).
print_stmt(T, Texts) :- print_stmt_data(T, Texts), !.

print_stmt_input(input(L206), T208) :- cl_9(L206, T207), flatten([['input'], T207, [';']], T208).
print_stmt(T, Texts) :- print_stmt_input(T, Texts), !.

print_stmt_format(format(Var215,G216), T218) :- grp_10(G216, T217), flatten([['format'], [Var215], T217, [';']], T218).
print_stmt(T, Texts) :- print_stmt_format(T, Texts), !.

print_stmt_length(length(L225), T227) :- cl_11(L225, T226), flatten([['length'], T226, [';']], T227).
print_stmt(T, Texts) :- print_stmt_length(T, Texts), !.

print_stmt_infile(infile(Dlm234), T236) :- print_expr(Dlm234, 0, T235), flatten([['infile'], ['datalines'], ['dsd'], ['dlm'], ['='], T235, ['truncover'], [';']], T236).
print_stmt(T, Texts) :- print_stmt_infile(T, Texts), !.

print_stmt_datalines(datalines(Rows239), T241) :- raw_text('datalines', Rows239, T240), flatten([T240], T241).
print_stmt(T, Texts) :- print_stmt_datalines(T, Texts), !.

print_stmt_set(set(In244), T246) :- print_rule_dsname(In244, T245), flatten([['set'], T245, [';']], T246).
print_stmt(T, Texts) :- print_stmt_set(T, Texts), !.

print_stmt_subset_if(subset_if(Cond249), T251) :- print_expr(Cond249, 0, T250), flatten([['if'], T250, [';']], T251).
print_stmt(T, Texts) :- print_stmt_subset_if(T, Texts), !.

print_stmt_if_then_set(if_then_set(Var258,Val259,In261), T263) :- print_expr(Val259, 0, T260), print_rule_dsname(In261, T262), flatten([['if'], [Var258], ['='], T260, ['then'], ['set'], T262, [';']], T263).
print_stmt(T, Texts) :- print_stmt_if_then_set(T, Texts), !.

print_stmt_merge(merge(L279), T281) :- cl_12(L279, T280), flatten([['merge'], T280, [';']], T281).
print_stmt(T, Texts) :- print_stmt_merge(T, Texts), !.

print_stmt_by(by(L287), T289) :- cl_14(L287, T288), flatten([['by'], T288, [';']], T289).
print_stmt(T, Texts) :- print_stmt_by(T, Texts), !.

print_stmt_proc_sql(proc_sql, T292) :- flatten([['proc'], ['sql'], [';']], T292).
print_stmt(T, Texts) :- print_stmt_proc_sql(T, Texts), !.

print_stmt_create_table_as(create_table_as(Out298,Select300), T302) :- print_rule_dsname(Out298, T299), print_rule_select_stmt(Select300, T301), flatten([['create'], ['table'], T299, ['as'], T301, [';']], T302).
print_stmt(T, Texts) :- print_stmt_create_table_as(T, Texts), !.

print_stmt_proc_print(proc_print(In307), T309) :- print_rule_dsname(In307, T308), flatten([['proc'], ['print'], ['data'], ['='], T308, [';']], T309).
print_stmt(T, Texts) :- print_stmt_proc_print(T, Texts), !.

print_stmt_title(title(Text312), T314) :- print_expr(Text312, 0, T313), flatten([['title'], T313, [';']], T314).
print_stmt(T, Texts) :- print_stmt_title(T, Texts), !.

print_stmt_empty(empty, T315) :- flatten([[';']], T315).
print_stmt(T, Texts) :- print_stmt_empty(T, Texts), !.

print_stmt_run(run, T317) :- flatten([['run'], [';']], T317).
print_stmt(T, Texts) :- print_stmt_run(T, Texts), !.

print_stmt_quit(quit, T319) :- flatten([['quit'], [';']], T319).
print_stmt(T, Texts) :- print_stmt_quit(T, Texts), !.

% ---- statement auxiliaries (print) ----
grp_2(when(Cond6,Then8), T10) :- print_expr(Cond6, 0, T7), print_expr(Then8, 0, T9), flatten([['when'], T7, ['then'], T9], T10).
cl_1_item(G12, T14) :- grp_2(G12, T13), flatten([T13], T14).
cl_1([X], Texts) :- !, cl_1_item(X, Texts).
cl_1([X|Xs], Texts) :- cl_1_item(X, TX), cl_1(Xs, TXs), flatten([TX, TXs], Texts).
grp_3(informat(Name39), T40) :- flatten([[Name39], ['.']], T40).
grp_5(proj(E104,O107,O111), T113) :- print_expr(E104, 0, T105), ( O107=some(As106) -> flatten([['as'], [As106]], T108) ; T108=[] ), ( O111=some(Len109) -> print_expr(Len109, 0, T110), flatten([['length'], ['='], T110], T112) ; T112=[] ), flatten([T105, T108, T112], T113).
cl_4_item(G116, T118) :- grp_5(G116, T117), flatten([T117], T118).
cl_4([X], Texts) :- !, cl_4_item(X, Texts).
cl_4([X|Xs], Texts) :- cl_4_item(X, TX), cl_4(Xs, TXs), flatten([TX, [','], TXs], Texts).
cl_6_item(K129, T131) :- print_expr(K129, 0, T130), flatten([T130], T131).
cl_6([X], Texts) :- !, cl_6_item(X, Texts).
cl_6([X|Xs], Texts) :- cl_6_item(X, TX), cl_6(Xs, TXs), flatten([TX, [','], TXs], Texts).
cl_7_item(Core159, T161) :- print_rule_select_core(Core159, T160), flatten([T160], T161).
cl_7([X], Texts) :- !, cl_7_item(X, Texts).
cl_7([X|Xs], Texts) :- cl_7_item(X, TX), cl_7(Xs, TXs), flatten([TX, ['union'], ['all'], TXs], Texts).
grp_8(orderby(Key169,C171), T173) :- print_expr(Key169, 0, T170), ( C171==desc -> T172=['desc'] ; ( C171==asc -> T172=['asc'] ; fail ) ), flatten([T170, T172], T173).
cl_9_item(V202, T204) :- print_rule_input_var(V202, T203), flatten([T203], T204).
cl_9([X], Texts) :- !, cl_9_item(X, Texts).
cl_9([X|Xs], Texts) :- cl_9_item(X, TX), cl_9(Xs, TXs), flatten([TX, TXs], Texts).
grp_10(fmt(Name212), T213) :- flatten([[Name212], ['.']], T213).
cl_11_item(V221, T223) :- print_rule_length_var(V221, T222), flatten([T222], T223).
cl_11([X], Texts) :- !, cl_11_item(X, Texts).
cl_11([X|Xs], Texts) :- cl_11_item(X, TX), cl_11(Xs, TXs), flatten([TX, TXs], Texts).
grp_13(src(Ds268,O271), T273) :- print_rule_dsname(Ds268, T269), ( O271=some(Flag270) -> flatten([['('], ['in'], ['='], [Flag270], [')']], T272) ; T272=[] ), flatten([T269, T272], T273).
cl_12_item(G275, T277) :- grp_13(G275, T276), flatten([T276], T277).
cl_12([X], Texts) :- !, cl_12_item(X, Texts).
cl_12([X|Xs], Texts) :- cl_12_item(X, TX), cl_12(Xs, TXs), flatten([TX, TXs], Texts).
cl_14_item(K284, T285) :- flatten([[K284]], T285).
cl_14([X], Texts) :- !, cl_14_item(X, Texts).
cl_14([X|Xs], Texts) :- cl_14_item(X, TX), cl_14(Xs, TXs), flatten([TX, TXs], Texts).

% ---- named rules (print) ----
print_rule_dsname(ds(Lib31,Name32), T33) :- flatten([[Lib31], ['.'], [Name32]], T33).
print_rule_dsname(ds(Name34), T35) :- flatten([[Name34]], T35).

print_rule_input_var(cvar(Name42), T43) :- flatten([[Name42], ['$']], T43).
print_rule_input_var(nvar(Name44,O47), T49) :- ( O47=some(G45) -> grp_3(G45, T46), flatten([[':'], T46], T48) ; T48=[] ), flatten([[Name44], T48], T49).

print_rule_length_var(clen(Name54,N55), T57) :- print_expr(N55, 0, T56), flatten([[Name54], ['$'], T56], T57).
print_rule_length_var(nlen(Name58,N59), T61) :- print_expr(N59, 0, T60), flatten([[Name58], T60], T61).

print_rule_from_source(table(Ds66,O69), T71) :- print_rule_dsname(Ds66, T67), ( O69=some(As68) -> flatten([[As68]], T70) ; T70=[] ), flatten([T67, T70], T71).
print_rule_from_source(subquery(Core72,O75), T77) :- print_rule_select_core(Core72, T73), ( O75=some(As74) -> flatten([[As74]], T76) ; T76=[] ), flatten([['('], T73, [')'], T76], T77).

print_rule_join_clause(left_join(Src88,On90), T92) :- print_rule_from_source(Src88, T89), print_expr(On90, 0, T91), flatten([['left'], ['join'], T89, ['on'], T91], T92).
print_rule_join_clause(inner_join(Src93,On95), T97) :- print_rule_from_source(Src93, T94), print_expr(On95, 0, T96), flatten([['inner'], ['join'], T94, ['on'], T96], T97).

print_rule_select_core(select_core(L135,From137,O141,O145,O149,O153), T155) :- cl_4(L135, T136), print_rule_from_source(From137, T138), ( O141=some(J139) -> print_rule_join_clause(J139, T140), flatten([T140], T142) ; T142=[] ), ( O145=some(Where143) -> print_expr(Where143, 0, T144), flatten([['where'], T144], T146) ; T146=[] ), ( O149=some(L147) -> cl_6(L147, T148), flatten([['group'], ['by'], T148], T150) ; T150=[] ), ( O153=some(Having151) -> print_expr(Having151, 0, T152), flatten([['having'], T152], T154) ; T154=[] ), flatten([['select'], T136, ['from'], T138, T142, T146, T150, T154], T155).

print_rule_select_stmt(select_stmt(L177,O181,O185), T187) :- cl_7(L177, T178), ( O181=some(G179) -> grp_8(G179, T180), flatten([['order'], ['by'], T180], T182) ; T182=[] ), ( O185=some(N183) -> print_expr(N183, 0, T184), flatten([['limit'], T184], T186) ; T186=[] ), flatten([T178, T182, T186], T187).


% precedence table: tightest level highest number
level_prec('pow', 90).
level_prec('unary', 80).
level_prec('mul', 70).
level_prec('add', 60).
level_prec('cat', 50).
level_prec('cmp', 40).
level_prec('not', 30).
level_prec('and', 20).
level_prec('or', 10).

print_expr(Term, MinPrec, Texts) :-
    expr_own(Term, OwnPrec, Inner),
    ( OwnPrec >= MinPrec -> Texts = Inner
    ; flatten([['('], Inner, [')']], Texts) ).

expr_own(pow(A,B), P, Texts) :- level_prec('pow', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['**'], TB], Texts).
expr_own(neg(A), P, Texts) :- level_prec('unary', P), print_expr(A, P, TA), flatten([['-'], TA], Texts).
expr_own(mul(A,B), P, Texts) :- level_prec('mul', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['*'], TB], Texts).
expr_own(div(A,B), P, Texts) :- level_prec('mul', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['/'], TB], Texts).
expr_own(add(A,B), P, Texts) :- level_prec('add', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['+'], TB], Texts).
expr_own(sub(A,B), P, Texts) :- level_prec('add', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['-'], TB], Texts).
expr_own(cat(A,B), P, Texts) :- level_prec('cat', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['||'], TB], Texts).
expr_own(eq(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['='], TB], Texts).
expr_own(eq(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['eq'], TB], Texts).
expr_own(ne(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['^='], TB], Texts).
expr_own(ne(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['~='], TB], Texts).
expr_own(ne(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['<>'], TB], Texts).
expr_own(ne(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['ne'], TB], Texts).
expr_own(lt(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['<'], TB], Texts).
expr_own(lt(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['lt'], TB], Texts).
expr_own(le(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['<='], TB], Texts).
expr_own(le(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['le'], TB], Texts).
expr_own(gt(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['>'], TB], Texts).
expr_own(gt(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['gt'], TB], Texts).
expr_own(ge(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['>='], TB], Texts).
expr_own(ge(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_expr(B, P1, TB), flatten([TA, ['ge'], TB], Texts).
expr_own(in(A,B), P, Texts) :- level_prec('cmp', P), P1 is P+1, print_expr(A, P1, TA), print_args(B, TB), flatten([TA, ['in'], ['('], TB, [')']], Texts).
expr_own(not(A), P, Texts) :- level_prec('not', P), print_expr(A, P, TA), flatten([['not'], TA], Texts).
expr_own(and(A,B), P, Texts) :- level_prec('and', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['and'], TB], Texts).
expr_own(or(A,B), P, Texts) :- level_prec('or', P), print_expr(A, P, TA), P1 is P+1, print_expr(B, P1, TB), flatten([TA, ['or'], TB], Texts).

% forms (print) — precedence 100: atomic, never need outer parens
expr_own(case_expr(L19,O23), 100, T25) :- cl_1(L19, T20), ( O23=some(Else21) -> print_expr(Else21, 0, T22), flatten([['else'], T22], T24) ; T24=[] ), flatten([['case'], T20, T24, ['end']], T25).
expr_own(missing, 100, T26) :- flatten([['.']], T26).
expr_own(star, 100, T27) :- flatten([['*']], T27).
expr_own(paren(E), 100, Texts) :- print_expr(E, 0, Inner), flatten([['('], Inner, [')']], Texts).
expr_own(call(N,Args), 100, Texts) :- print_args(Args, ArgsT), flatten([[N], ['('], ArgsT, [')']], Texts).
expr_own(col(N,F), 100, Texts) :- flatten([[N], ['.'], [F]], Texts).
expr_own(subquery_expr(V), 100, Texts) :- print_rule_select_core(V, Inner), flatten([['('], Inner, [')']], Texts).

% leaves (print)
expr_own(lit(N), 100, [NT]) :- number(N), !, format(atom(NT), '~w', [N]).
expr_own(lit(S), 100, [QT]) :- atom(S), \+ number(S), quote_plain(0''', S, QT).
expr_own(col(N), 100, [N]) :- atom(N).

print_args([], []).
print_args([A], Texts) :- !, print_expr(A, 0, Texts).
print_args([A|As], Texts) :- print_expr(A, 0, TA), print_args(As, TAs), flatten([TA, [','], TAs], Texts).
